import {session,authRequest,logout,clearPrivateCache} from './auth.js';
import {emitterContext} from './emitters.js';
export function createUserViews({shell,heading,esc,icon,toast,modal,beforeAction,isAdmin=()=>false}){
 let users=[];
 const roleName=role=>role==='admin'?'Administrador':'Usuario normal';
 const passwordField=(id,label,name,required=true)=>`<div class="field full"><label for="${id}">${label}</label><div class="password-field"><input id="${id}" name="${name}" type="password" autocomplete="new-password" minlength="6" maxlength="128" ${required?'required':''}><button class="password-toggle" type="button" data-password-toggle="${id}" aria-label="Mostrar contraseña">Mostrar</button></div></div>`;
 async function renderUsers(){
  if(!session.user.isRoot)return renderAccount();
  shell(heading('El equipo','Una cuenta por persona y accesos independientes para cada empresa o autónomo.',`<button class="btn primary" data-user-action="create">${icon('plus')} Crear usuario</button>`)+`<section class="users-role-guide"><article class="panel"><span class="badge">Administrador</span><h2>Una visión completa de la empresa</h2><p>Acceso completo a las facturas, cobros, clientes y configuración de los emisores asignados. La cuenta principal gestiona usuarios y accesos.</p></article><article class="panel"><span class="badge draft">Usuario normal</span><h2>Su trabajo y sus cuentas</h2><p>Crea y consulta sus facturas y gestiona sus cobros y análisis. El directorio de clientes es compartido.</p></article></section><section class="panel" id="users-list"><div class="empty">Cargando equipo…</div></section><section class="panel formpanel users-security"><h2>Acceso y contraseñas</h2><p>Las cuentas nuevas entran con una contraseña temporal y eligen una personal en su primera sesión. Desactivar una cuenta conserva sus facturas y cierra sus sesiones.</p><p class="summary-note">La cuenta principal conserva la gestión de los emisores y los accesos.</p></section>`,'Usuarios');
  try{const response=await fetch('/api/users');const result=await response.json();if(!response.ok)throw Error(result.error);users=result.users;const panel=document.querySelector('#users-list');if(!panel)return;
   panel.innerHTML=`<div class="tablewrap"><table class="users-table"><thead><tr><th scope="col">Persona</th><th scope="col">Emisores y permisos</th><th scope="col">Acceso</th><th scope="col" aria-label="Acciones"></th></tr></thead><tbody>${users.map(user=>`<tr><td><strong>${esc(user.name)} ${user.id===session.user.id?'<span class="current-user-label">Tú</span>':''}</strong><small class="cell-secondary">${esc(user.email)}</small></td><td class="user-access-list">${user.isRoot?'Cuenta principal · todos los emisores':user.memberships?.length?user.memberships.map(m=>`${esc(emitterContext.emitters.find(e=>e.id===m.emitterId)?.name||'Emisor')} · ${roleName(m.role)}`).join('<br>'):'Sin emisores asignados'}</td><td><span class="badge ${!user.active?'draft':''}">${user.active?'Activo':'Desactivado'}</span>${user.active&&user.mustChangePassword?'<small class="cell-secondary">Contraseña temporal pendiente</small>':''}</td><td><button class="btn" data-edit-user="${esc(user.id)}" aria-label="Editar usuario ${esc(user.name)}">${icon('edit')} Editar</button></td></tr>`).join('')}</tbody></table></div><div class="tablefoot">${users.filter(u=>u.active).length} usuarios activos · ${users.length} cuentas</div>`;
  }catch(error){toast(error.message);const panel=document.querySelector('#users-list');if(panel)panel.textContent='No se ha podido cargar el equipo. Recarga la página para volver a intentarlo.';}
 }
 function renderAccount(){
  const user=session.user;
  shell(heading('Mi cuenta','Tu acceso a '+esc('arquitecturadeguardia Finance'))+`<div class="account-layout"><section class="panel formpanel"><h2>${esc(user.name)}</h2><p class="account-email">${esc(user.email)}</p><span class="badge">${user.isRoot?'Cuenta principal':isAdmin()?'Administrador del emisor':'Usuario normal'}</span><p class="summary-note">${user.isRoot?'Gestionas los emisores y el acceso de los usuarios.':isAdmin()?'Tienes acceso a toda la facturación del emisor seleccionado.':'Tus listados, exportaciones y análisis muestran tus propias facturas del emisor seleccionado.'}</p><button class="btn" data-user-action="logout">${icon('logout')} Cerrar sesión</button></section><section class="panel formpanel"><h2>Cambiar mi contraseña</h2><form id="account-password-form"><div class="fields"><div class="field full"><label for="account-current">Contraseña actual</label><input id="account-current" name="currentPassword" type="password" autocomplete="current-password" required></div>${passwordField('account-new','Nueva contraseña','password')}${passwordField('account-confirm','Repite la nueva contraseña','confirm')}</div><p class="summary-note">Entre 6 y 128 caracteres. Puedes utilizar una frase con varias palabras. Al cambiarla se cerrarán las sesiones de otros dispositivos.</p><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Guardar nueva contraseña</button></form></section></div>`,'Mi cuenta');
 }
 async function userModal(id){
  await beforeAction();const user=users.find(u=>u.id===id),isSelf=id===session.user.id,activeRole=user?.isRoot?'admin':user?.memberships?.find(m=>m.emitterId===emitterContext.active.id)?.role||'member';
  modal.className='';modal.innerHTML=`<button class="iconbtn close" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button><h2>${user?'Editar usuario':'Crear usuario'}</h2><p>${user?'Actualiza sus datos y los emisores a los que puede acceder.':'Asigna los emisores y comparte la contraseña temporal por un canal privado.'}</p><form id="user-form" data-id="${esc(id||'')}"><div class="fields"><div class="field full"><label for="user-name">Nombre</label><input id="user-name" name="name" value="${esc(user?.name||'')}" required maxlength="100" autocomplete="off"></div><div class="field full"><label for="user-email">Correo electrónico</label><input id="user-email" name="email" type="email" value="${esc(user?.email||'')}" required maxlength="254" autocomplete="off"></div><div class="field full"><label for="user-role">Rol</label><select id="user-role" name="role"><option value="member" ${activeRole!=='admin'?'selected':''}>Usuario normal · sus facturas y cobros</option><option value="admin" ${activeRole==='admin'?'selected':''}>Administrador · emisor completo</option></select><small>Atajo para el emisor seleccionado. Puedes ajustar cada acceso más abajo.</small></div>${user?`<div class="field full"><label for="user-active">Acceso a la empresa</label><select id="user-active" name="active"><option value="true" ${user.active?'selected':''}>Activo</option><option value="false" ${!user.active?'selected':''}>Desactivado</option></select><small>Desactivar conserva sus documentos y cierra sus sesiones.</small></div>`:''}${!isSelf?passwordField('user-password',user?'Restablecer contraseña (opcional)':'Contraseña temporal','password',!user):''}</div>${!isSelf?`<div class="temporary-password-tools"><button class="btn ghost" type="button" data-user-action="generate">Generar contraseña temporal</button><small>${user?'Déjala vacía para conservar la contraseña actual. Restablecerla cierra sus sesiones.':'La persona elegirá una contraseña personal al entrar por primera vez.'}</small></div>`:'<p class="summary-note">Puedes cambiar tu contraseña desde Mi cuenta.</p>'}${user?.isRoot?'<p class="notice">La cuenta principal tiene acceso a todos los emisores.</p>':`<fieldset class="membership-fields"><legend>Acceso por empresa o autónomo</legend>${emitterContext.emitters.map(e=>`<div class="membership-row"><label for="access-${e.id}">${esc(e.name)}<small>${esc(e.nif)}${e.active?'':' · Archivado'}</small></label><select id="access-${e.id}" data-membership-emitter="${esc(e.id)}" aria-label="Acceso a ${esc(e.name)}">${[['none','Sin acceso'],['member','Usuario normal'],['admin','Administrador']].map(([value,label])=>`<option value="${value}" ${((user?.memberships?.find(m=>m.emitterId===e.id)?.role)||(!user&&e.id===emitterContext.active.id?'member':'none'))===value?'selected':''}>${label}</option>`).join('')}</select></div>`).join('')}</fieldset>`}<div class="form-error" role="alert"></div><div class="actions"><button class="btn ghost" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">${user?'Guardar usuario':'Crear usuario'}</button></div></form>`;
  if(!modal.open)modal.showModal();document.querySelector('#user-name').focus();
 }
 document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
  if(button.dataset.editUser)return await userModal(button.dataset.editUser);
  switch(button.dataset.userAction){
   case'create':await userModal();break;
   case'generate':{const bytes=crypto.getRandomValues(new Uint8Array(20)),alphabet='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789-_';const input=document.querySelector('#user-password');input.value=[...bytes].map(n=>alphabet[n%alphabet.length]).join('');input.type='text';input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();break;}
   case'logout':await beforeAction();await logout();break;
  }
 }catch(error){toast(error.message);}});
 document.addEventListener('change',event=>{if(event.target.id==='user-role'){const active=document.querySelector('[data-membership-emitter="'+CSS.escape(emitterContext.active.id)+'"]');if(active)active.value=event.target.value;}else if(event.target.dataset.membershipEmitter===emitterContext.active.id&&event.target.value!=='none'){document.querySelector('#user-role').value=event.target.value;}});
 document.addEventListener('submit',async event=>{
  const form=event.target;if(!['user-form','account-password-form'].includes(form.id))return;event.preventDefault();const button=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');button.disabled=true;error.textContent='';
  try{
   const data=Object.fromEntries(new FormData(form));
   if(form.id==='user-form'){
    const id=form.dataset.id;const accesses=[...form.querySelectorAll('[data-membership-emitter]')];if(accesses.length)data.memberships=accesses.filter(input=>input.value!=='none').map(input=>({emitterId:input.dataset.membershipEmitter,role:input.value}));if(id)data.active=data.active==='true';if(!data.password)delete data.password;
    const result=await authRequest(id?'/api/users/'+encodeURIComponent(id):'/api/users',data);modal.close();modal.className='';
    if(id===session.user.id){if(result.user.email!==session.user.email||result.user.role!==session.user.role||!result.user.active){clearPrivateCache();location.replace('/');return;}session.user=result.user;}
    await renderUsers();toast(id?'Usuario actualizado':'Usuario creado. Al entrar elegirá su contraseña personal.');
   }else{
    if(data.password!==data.confirm)throw Error('Las contraseñas no coinciden.');await beforeAction();session.user=(await authRequest('/api/auth/password',data)).user;form.reset();toast('Contraseña actualizada. Las otras sesiones se han cerrado.');
   }
  }catch(cause){error.textContent=cause.message;}finally{button.disabled=false;}
 });
 return {renderUsers,renderAccount};
}
